package com.bank.rsocket.controller;

import com.bank.rsocket.dto.BalanceResponse;
import com.bank.rsocket.dto.PriceTick;
import lombok.extern.slf4j.Slf4j;
import org.springframework.messaging.handler.annotation.MessageMapping;
import org.springframework.stereotype.Controller;
import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;
import java.math.BigDecimal;
import java.time.Duration;

@Slf4j
@Controller
public class PriceController {

    // 1) REQUEST-RESPONSE: one balance query → one answer
    @MessageMapping("account.balance")
    public Mono<BalanceResponse> balance(String accountId) {
        log.info("Request-response balance for {}", accountId);
        BigDecimal bal = "SAV2001".equals(accountId)
            ? new BigDecimal("1000000") : new BigDecimal("250000");
        return Mono.just(new BalanceResponse(accountId, bal));
    }

    // 2) FIRE-AND-FORGET: audit ping, no response
    @MessageMapping("audit.ping")
    public Mono<Void> auditPing(String event) {
        log.info("Fire-and-forget audit event: {}", event);
        return Mono.empty();
    }

    // 3) REQUEST-STREAM: live price feed — many responses, backpressure-aware
    @MessageMapping("price.stream")
    public Flux<PriceTick> priceStream(String symbol) {
        log.info("Request-stream price feed for {}", symbol);
        return Flux.interval(Duration.ofMillis(200))
                   .map(seq -> new PriceTick(symbol,
                        new BigDecimal("2450").add(BigDecimal.valueOf(seq)), seq))
                   .take(5); // demo: 5 ticks
    }

    // 4) REQUEST-CHANNEL: bidirectional — orders in, acks out, both streaming
    @MessageMapping("order.channel")
    public Flux<String> orderChannel(Flux<String> orders) {
        log.info("Request-channel order session opened");
        return orders.map(o -> "ACK " + o + " accepted");
    }
}
