package com.bank.rsocket.client;

import com.bank.rsocket.dto.BalanceResponse;
import com.bank.rsocket.dto.PriceTick;
import lombok.extern.slf4j.Slf4j;
import org.springframework.messaging.rsocket.RSocketRequester;
import reactor.core.publisher.Flux;

@Slf4j
public class TradingClient {
    private final RSocketRequester requester;
    public TradingClient(RSocketRequester requester) { this.requester = requester; }

    public void runAll() {
        // request-response
        requester.route("account.balance").data("SAV2001")
            .retrieveMono(BalanceResponse.class)
            .subscribe(b -> log.info("Balance: {} Rs.{}", b.accountId(), b.balance()));

        // fire-and-forget
        requester.route("audit.ping").data("Rajesh logged in")
            .send().subscribe();

        // request-stream WITH backpressure: only pull 3 ticks at a time
        requester.route("price.stream").data("RELIANCE")
            .retrieveFlux(PriceTick.class)
            .limitRate(3) // application-level demand: request(3)
            .subscribe(t -> log.info("Tick {} Rs.{}", t.seq(), t.price()));

        // request-channel: stream orders, receive acks
        Flux<String> orders = Flux.just("BUY 100 RELIANCE", "SELL 40 RELIANCE");
        requester.route("order.channel").data(orders)
            .retrieveFlux(String.class)
            .subscribe(ack -> log.info("Server: {}", ack));
    }
}
